        internal static void ProcessRewardScreen(Bitmap file = null)
        {
            #region initializers
            if (_tesseractInitFailed || _tesseractService == null)
            {
                Main.AddLog("ERROR: Cannot process reward screen - TesseractService is null or failed to initialize");
                return;
            }

            if (processingActive)
            {
                Main.StatusUpdate("Still Processing Reward Screen", 2);
                return;
            }

            var primeRewards = new List<string>();

            processingActive = true;
            Main.StatusUpdate("Processing...", 0);
            Main.AddLog("----  Triggered Reward Screen Processing  ------------------------------------------------------------------");

            DateTime time = DateTime.UtcNow;
            timestamp = time.ToString("yyyy-MM-dd HH-mm-ssffffff", Main.culture);
            var watch = new Stopwatch();
            watch.Start();
            long start = watch.ElapsedMilliseconds;

            List<Bitmap> parts;

            if (file != null)
            {
                bigScreenshot = file;
            } else
            {
                var screenshot = CaptureScreenshot();
                if (screenshot == null)
                {
                    Main.AddLog("Processing failed: Screenshot failed");
                    return;
                }
                bigScreenshot = screenshot;
            }

            try
            {
				    parts = ExtractPartBoxAutomatically(out uiScaling, out _, bigScreenshot);
            }
            catch (Exception e)
            {
                processingActive = false;
                Debug.WriteLine(e);
                return;
            }


            int engineCount = Math.Min(parts.Count, _tesseractService.Engines.Length);
            firstChecks = new string[parts.Count];
            Task[] tasks = new Task[engineCount];
            for (int i = 0; i < engineCount; i++)
            {
                int tempI = i;
                tasks[i] = Task.Run(() => { firstChecks[tempI] = OCR.GetTextFromImage(parts[tempI], _tesseractService.Engines[tempI]);});
            }
            Task.WaitAll(tasks);
            // Process remaining parts sequentially if more parts than engines
            for (int i = engineCount; i < parts.Count; i++)
            {
                firstChecks[i] = OCR.GetTextFromImage(parts[i], _tesseractService.FirstEngine);
            }

            // Remove any empty (or suspiciously short) items from the array
            firstChecks = firstChecks.Where(s => !string.IsNullOrEmpty(s) && PartNameValid(s)).ToArray();
            if (firstChecks == null || firstChecks.Length == 0)
            {
                processingActive = false;
                Main.AddLog(("----  Partial Processing Time, couldn't find rewards " + (watch.ElapsedMilliseconds - start) + " ms  ------------------------------------------------------------------------------------------").Substring(0, 108));
                Main.StatusUpdate("Couldn't find any rewards to display", 2);
                if (firstChecks == null)
                {
                    Main.RunOnUIThread(() =>
                    {
                        Main.SpawnErrorPopup(time);
                    });
                }
                return;
            }
            double bestPlat = 0;
            int bestDucat = 0;
            int bestPlatItem = 0;
            int bestDucatItem = 0;
            List<int> unownedItems = new List<int>();

            #endregion

            try
            {
            #region processing data
            if (firstChecks.Length > 0)
            {
                numberOfRewardsDisplayed = firstChecks.Length;
                clipboard = string.Empty;
                int width = (int)(pixleRewardWidth * _window.ScreenScaling * uiScaling) + 10;
                int startX = _window.Center.X - width / 2 + (int)(width * 0.004);
                if (firstChecks.Length % 2 == 1) { startX += width / 8; }
                if (firstChecks.Length <= 2) { startX += 2 * (width / 8); }
                int overWid = (int)(width / (4.1 * _window.DpiScaling));
                int startY = (int)(_window.Center.Y / _window.DpiScaling - 20 * _window.ScreenScaling * uiScaling);
                int partNumber = 0;
                bool hideRewardInfo = false;
                for (int i = 0; i < firstChecks.Length; i++)
                {
                    string part = firstChecks[i];
                    #region found a part
                    string correctName = Main.dataBase.GetPartName(part, out firstProximity[i], false, out _);

                    // Filter out results with excessively high Levenshtein distances (indicating no valid match)
                    // 9999 is the default value when no match was found, and anything above 50% of string length is likely invalid
                    if (firstProximity[i] == 9999 || firstProximity[i] > GetMaxAllowedLevenshteinDistance(part.Length) || string.IsNullOrEmpty(correctName))
                    {
                        Main.AddLog($"Rejected junk match: '{part}' with distance {firstProximity[i]}");
                        continue; // Skip this part entirely
                    }

                    string primeSetName = Data.GetSetName(correctName);
                    JObject job = (JObject)Main.dataBase.marketData.GetValue(correctName);
                    JObject primeSet = (JObject)Main.dataBase.marketData.GetValue(primeSetName);

                    // Guard against null market data
                    if (job == null || job["ducats"] == null)
                    {
                        Main.AddLog($"MARKET DATA: No market data or ducats found for '{correctName}', skipping");
                        continue;
                    }

                    string ducats = job["ducats"].ToObject<string>();
                    if (!int.TryParse(ducats, System.Globalization.NumberStyles.Integer, Main.culture, out int ducatValue) || ducatValue == 0)
                    {
                        hideRewardInfo = true;
                    }

                    // Check if this is an ignored item using both English name AND raw OCR text (localized)
                    // This catches items even if GetPartName() fails to convert properly
                    if (Main.dataBase.IsIgnoredItem(correctName) || Main.dataBase.IsIgnoredItem(part))
                    {
                        hideRewardInfo = true;
                    }

                    primeRewards.Add(correctName);
                    string plat = job["plat"].ToObject<string>();
                    string primeSetPlat = null;
                    if (primeSet != null)
                    {
                        primeSetPlat = (string)primeSet["plat"];
                    }
                    double platinum = double.Parse(plat, styles, Main.culture);
                    string volume = job["volume"].ToObject<string>();
                    bool vaulted = SafeCall(() => Main.dataBase.IsPartVaulted(correctName), false, "IsPartVaulted", correctName);
                    bool mastered = SafeCall(() => Main.dataBase.IsPartMastered(correctName), false, "IsPartMastered", correctName);
                    string partsOwned = SafeCall(() => Main.dataBase.PartsOwned(correctName), "0", "PartsOwned", correctName);
                    string partsCount = SafeCall(() => Main.dataBase.PartsCount(correctName), "0", "PartsCount", correctName);
                    int duc = ducatValue;
                    #endregion

                    #region highlighting
                    if (platinum >= bestPlat)
                    {
                        bestPlat = platinum; bestPlatItem = i;
                        if (duc >= bestDucat)
                        {
                            bestDucat = duc; bestDucatItem = i;
                        }
                    }
                    if (duc > bestDucat)
                    {
                        bestDucat = duc; bestDucatItem = i;
                    }
                    if (duc > 0)
                    {
                        if (!mastered && int.Parse(partsOwned, Main.culture) < int.Parse(partsCount, Main.culture))
                        {
                            unownedItems.Add(i);
                        }
                    }
                    #endregion

                    #region clipboard
                    if (platinum > 0)
                    {
                        if (!string.IsNullOrEmpty(clipboard)) { clipboard += "-  "; }

                        // Get localized name for clipboard (uses current WFInfo locale)
                        string localizedName = Main.dataBase.GetLocalizedNameForClipboard(correctName);
                        // Remove blueprint terms for the current language
                        localizedName = Main.dataBase.RemoveBlueprintTerms(localizedName);

                        clipboard += "[" + localizedName + "]: " + plat + ":platinum: ";

                        if (primeSetPlat != null)
                        {
                            clipboard += "Set: " + primeSetPlat + ":platinum: ";
                        }

                        if (_settings.ClipboardVaulted)
                        {
                            clipboard += ducats + ":ducats:";
                            if (vaulted)
                                clipboard += "(V)";
                        }
                    }

                    if ((partNumber == firstChecks.Length - 1) && (!string.IsNullOrEmpty(clipboard)))
                    {
                        clipboard += _settings.ClipboardTemplate;
                    }
                    #endregion

                    #region display part
                    Main.RunOnUIThread(() =>
                    {
                        Overlay.rewardsDisplaying = true;

                        if (_settings.IsOverlaySelected)
                        {
                            Main.overlays[partNumber].LoadTextData(correctName, plat, primeSetPlat, ducats, volume, vaulted, mastered, $"{partsOwned} / {partsCount}", "", hideRewardInfo, false);
                            Main.overlays[partNumber].Resize(overWid);
                            Main.overlays[partNumber].Display((int)((startX + width / 4 * partNumber + _settings.OverlayXOffsetValue) / _window.DpiScaling), startY + (int)(_settings.OverlayYOffsetValue / _window.DpiScaling), _settings.Delay);
                        }
                        else if (!_settings.IsLightSelected)
                        {
                            Main.window.loadTextData(correctName, plat, primeSetPlat, ducats, volume, vaulted, mastered, $"{partsOwned} / {partsCount}", partNumber, true, hideRewardInfo);
                        }
                        //else
                        //Main.window.loadTextData(correctName, plat, ducats, volume, vaulted, $"{partsOwned} / {partsCount}", partNumber, false, hideRewardInfo);

                        if (_settings.Clipboard && !string.IsNullOrEmpty(clipboard))
                            Clipboard.SetText(clipboard);

                    });
                    partNumber++;
                    hideRewardInfo = false;
                    #endregion
                }
                var end = watch.ElapsedMilliseconds;
                Main.StatusUpdate("Completed processing (" + (end - start) + "ms)", 0);

                if (Main.listingHelper.PrimeRewards.Count == 0 || Main.listingHelper.PrimeRewards.Last().Except(primeRewards).ToList().Count != 0)
                {
                    Main.listingHelper.PrimeRewards.Add(primeRewards);
                }

                if (_settings.HighlightRewards)
                {
                    Main.RunOnUIThread(() =>
                    {
                        foreach (int item in unownedItems)
                        {
                            Main.overlays[item].BestOwnedChoice();
                        }
                        Main.overlays[bestDucatItem].BestDucatChoice();
                        Main.overlays[bestPlatItem].BestPlatChoice();
                    });
                }
                Main.AddLog(("----  Total Processing Time " + (end - start) + " ms  ------------------------------------------------------------------------------------------").Substring(0, 108));
                watch.Stop();
            }
            #endregion 

            if (_settings.IsLightSelected && clipboard.Length > 3) //light mode doesn't have any visual confirmation that the ocr has finished, thus we use a sound to indicate this.
            {
                _soundPlayer.Play();
            }


            (new DirectoryInfo(Main.AppPath + @"\Debug\")).GetFiles()
                .Where(f => f.CreationTime < DateTime.Now.AddHours(-1 * _settings.ImageRetentionTime))
                .ToList().ForEach(f => f.Delete());

            if (partialScreenshot != null)
            {
                partialScreenshot.Save(Main.AppPath + @"\Debug\PartBox_" + timestamp + ".png");
                partialScreenshot.Dispose();
                partialScreenshot = null;
            }
            } // end try
            finally
            {
                processingActive = false;
            }

        }

