        public static string GetTextFromImage(Bitmap image, TesseractEngine engine)
        {
            string ret = "";

            // For CJK locales, try multiple PSM modes and pick the best result.
            // For Latin-based locales, SingleBlock is sufficient — skip the second pass for performance.
            PageSegMode[] preferredModes = IsCJKLocale()
                ? new[] { PageSegMode.SingleBlock, PageSegMode.SingleColumn }
                : new[] { PageSegMode.SingleBlock };

            Dictionary<PageSegMode, string> modeResults = new Dictionary<PageSegMode, string>();
            Dictionary<PageSegMode, double> modeScores = new Dictionary<PageSegMode, double>();

            foreach (var mode in preferredModes)
            {
                try
                {
                    using (Page page = engine.Process(image, mode))
                    {
                        string text = page.GetText().Trim();
                        modeResults[mode] = text;

                        // Score the result
                        double score = ScoreTextResult(text, mode);
                        modeScores[mode] = score;

                        // Early exit if we got a very good result (has CJK chars and reasonable length)
                        if (score > 50 && text.Length > 6 && text.Any(c => 
                            (c >= 0xAC00 && c <= 0xD7AF) ||  // Korean Hangul
                            (c >= 0x4E00 && c <= 0x9FFF) ||  // CJK Unified Ideographs
                            (c >= 0x3400 && c <= 0x4DBF)))   // CJK Extension A
                        {
                            ret = text;
                            break; // Exit early for performance
                        }
                    }
                }
                catch (Exception e)
                {
                    Main.AddLog($"OCR extraction failed in GetTextFromImage: {e.Message}\n{e}");
                    modeResults[mode] = "";
                    modeScores[mode] = 0;
                }
            }

            // If we didn't exit early, select the best result
            if (string.IsNullOrEmpty(ret))
            {
                var bestMode = modeScores.OrderByDescending(kvp => kvp.Value).First().Key;
                ret = modeResults[bestMode] ?? "";
            }

            // Tesseract now handles character filtering via CharacterWhitelist
            return ret.Trim();
        }
        /// <summary>
        /// Scores OCR text results for quality assessment
        /// </summary>
        private static double ScoreTextResult(string text, PageSegMode mode)
        {
            if (string.IsNullOrEmpty(text))
                return 0;

            double score = 0;

            // Base score for text length
            score += Math.Min(text.Length, 100);

            // Korean character detection bonus
            int koreanChars = text.Count(c => c >= 0xAC00 && c <= 0xD7AF);
            // CJK character detection bonus (Chinese Simplified/Traditional)
            int cjkChars = text.Count(c => (c >= 0x4E00 && c <= 0x9FFF) || (c >= 0x3400 && c <= 0x4DBF));
            int nonLatinChars = koreanChars + cjkChars;
            if (nonLatinChars > 0)
            {
                score += 20; // Bonus for CJK text
                score += Math.Min(nonLatinChars * 2, 30); // Additional bonus per CJK character
            }

            // Line count analysis
            string[] lines = text.Split(NewlineSplitChars, StringSplitOptions.RemoveEmptyEntries);
            score += Math.Min(lines.Length * 5, 25);

            // Mode-specific scoring
            if (mode == PageSegMode.SingleBlock)
            {
                // SingleBlock should work well for single items (up to 3 lines with word wrapping)
                if (lines.Length >= 1 && lines.Length <= 3)
                    score += 20; // Higher bonus for optimal single item blocks
                if (nonLatinChars > 0 && lines.Length >= 2)
                    score += 15; // Extra bonus for multi-line CJK text (wrapped item names)
            }
            else if (mode == PageSegMode.SingleColumn)
            {
                // SingleColumn should handle stacked lines well in reward slots
                if (lines.Length >= 1 && lines.Length <= 4)
                    score += 15; // Good for vertically stacked reward text
                if (nonLatinChars > 0)
                    score += 10; // Bonus for CJK text in column layout
            }
            else if (mode == PageSegMode.SparseText)
            {
                // SparseText should find multiple distinct text regions
                if (lines.Length >= 2)
                    score += 10;
            }

            // Penalty for too much whitespace (indicates poor segmentation)
            double whitespaceRatio = (double)text.Count(char.IsWhiteSpace) / text.Length;
            if (whitespaceRatio > 0.3)
                score -= 10;

            return Math.Max(score, 0);
        }

        internal static List<string> SeparatePlayers(Bitmap image, TesseractEngine engine)
        {

            // Values to determine whether there's an even or odd number of players
            int wid = image.Width / 4;
            int subwid = wid / 2;
            int subsubwid = subwid / 4;

            // 3 player values
            //  left  mid  right
            int mid = image.Width / 2;
            int left = mid - wid;
            int right = mid + wid;

            // list of centers for each potential set of text
            //   alternates between even locations and odd locations
            int[] allLocs = new int[] { left - subwid, left, left + subwid, mid, right - subwid, right, right + subwid };

            // Point system to determine if the player count is even or odd
            //    At the end of the calc, whichever has more wins
            int oddCount = 0;
            int evenCount = 0;

            // 2d array - words with bounds (1 dimensional)
            /*   [
             *     [start, end, word_ind, word_ind, ...] -- horizontal start and end position of this part and the list of words with it
             *     ...
             *   ]
            */
            List<List<int>> arr2D = new List<List<int>>();
            List<string> words = new List<string>();
            using (Page page = engine.Process(image))
            {
                using (var iter = page.GetIterator())
                {
                    iter.Begin();
                    do
                    {
                        iter.TryGetBoundingBox(PageIteratorLevel.Word, out Rect outRect);
                        string word = iter.GetText(PageIteratorLevel.Word);
                        if (word != null)
                        {
                            // Tesseract now handles character filtering via CharacterWhitelist
                            word = word.Trim();
                            if (word.Length > 0)
                            {
                                int topOrBot = outRect.Y1 > (outRect.Height * 3 / 4) ? 0 : 1;
                                for (int i = 0; i < allLocs.Length; i++)
                                {
                                    int bot = allLocs[i] - subsubwid;
                                    int top = allLocs[i] + subsubwid;
                                    if (bot <= outRect.X2 && top >= outRect.X1)
                                    {
                                        if ((i & 1) == 0)
                                            evenCount++;
                                        else
                                            oddCount++;
                                        break;
                                    }
                                }
                                List<int> temp = new List<int> {
                                    outRect.X1,
                                    outRect.X2,
                                    words.Count,
                                    topOrBot
                                };
                                arr2D.Add(temp);
                                words.Add(word);
                            }
                        }

                        // Giant blob of shit
                        // Translates to:
                        //   keep going while there's words left in the line
                        //           or while there's lines left in the para
                        //           or while there's paras left in the block
                        //           or while there's blocks left 
                    } while (iter.Next(PageIteratorLevel.TextLine, PageIteratorLevel.Word) || iter.Next(PageIteratorLevel.Para, PageIteratorLevel.TextLine) || iter.Next(PageIteratorLevel.Block, PageIteratorLevel.Para) || iter.Next(PageIteratorLevel.Block));
                }
            }
            arr2D.Sort(new OCR.Arr2D_Compare());

            List<string> ret = new List<string>();

            // time to group text together
            // get left side of part text area
            //    and width of text area
            //    group all text within
            //    go to the next one

            // position the left correctly based on part boxes
            if (oddCount > evenCount)
                left -= subwid;
            else
                left -= wid;

            string currPartTop = "";
            string currPartBot = "";

            int ind = 0;
            for (; ind < arr2D.Count && arr2D[ind][0] < left; ind++) ;


            for (; ind < arr2D.Count; ind++)
            {
                if (arr2D[ind][0] >= left + wid)
                {
                    left += wid;
                    ret.Add((currPartTop.Trim() + " " + currPartBot.Trim()).Trim());
                    currPartTop = "";
                    currPartBot = "";
                }
                if (arr2D[ind][3] == 1)
                    currPartTop += words[arr2D[ind][2]] + " ";
                else
                    currPartBot += words[arr2D[ind][2]] + " ";
            }
            ret.Add((currPartTop.Trim() + " " + currPartBot.Trim()).Trim());


            Main.AddLog((ret[0].Length == 0 ? ret.Count - 1 : ret.Count) + " Players Found -- Odds (" + oddCount + ") vs Evens (" + evenCount + ")");

            if ((oddCount == 0 && evenCount == 0) || oddCount == evenCount)
            { //Detected 0 rewards
                return null;
            }

            // Remove any empty items from the array
            return ret.Where(s => !string.IsNullOrEmpty(s)).ToList();
        }

        private class Arr2D_Compare : IComparer<List<int>>
        {
            public int Compare(List<int> x, List<int> y)
            {
                return x[0].CompareTo(y[0]);
            }
        }

        /// <summary>
        /// Captures 200x200 px around the theme probe area instead of full screen.
        /// Returns the crop bitmap and the window-space origin (cropX, cropY) so the
        /// caller can translate probe coordinates into crop-local coordinates.
        /// </summary>
        private static (Bitmap bitmap, int originX, int originY) CaptureThemeRegion()
        {
            _window.UpdateWindow();

            double sc = _window.ScreenScaling * Math.Max(uiScaling, 0.5);
            int probeX = (int)Math.Round(150 * sc);
            int probeY1 = (int)Math.Round(85 * sc);

            // Square 200px around the probe column
            const int margin = 100;
            const int side = margin * 2;
            var window = _window.Window;

            int cropX = Math.Max(0, probeX - margin);
            int cropY = Math.Max(0, probeY1 - margin);
            cropX = Math.Min(cropX, Math.Max(0, window.Width  - side));
            cropY = Math.Min(cropY, Math.Max(0, window.Height - side));

            int screenX = window.Left + cropX;
            int screenY = window.Top  + cropY;

            // Select screenshot service (same logic as CaptureScreenshot)
            IScreenshotService screenshot;
            if (_windowsScreenshot == null)
            {
                screenshot = _gdiScreenshot;
            }
            else
            {
                switch (_settings.HdrSupport)
                {
                    case HdrSupportEnum.On:
                        screenshot = _windowsScreenshot;
                        break;
                    case HdrSupportEnum.Off:
                        screenshot = _gdiScreenshot;
                        break;
                    case HdrSupportEnum.Auto:
                        bool isHdr = _hdrDetector.IsHDR;
                        screenshot = isHdr ? _windowsScreenshot : _gdiScreenshot;
                        break;
                    default:
                        throw new NotImplementedException($"HDR support option '{_settings.HdrSupport}' does not have a corresponding screenshot service.");
                }
            }

            if (ReferenceEquals(screenshot, _windowsScreenshot) && !screenshot.IsAvailable)
            {
                screenshot = _gdiScreenshot;
            }

            Bitmap region;
            if (screenshot is GdiScreenshotService)
            {
                // Direct region capture via GDI — no full-screen copy
                region = new Bitmap(side, side, PixelFormat.Format32bppArgb);
                using (Graphics g = Graphics.FromImage(region))
                {
                    g.CopyFromScreen(screenX, screenY, 0, 0, new Size(side, side), CopyPixelOperation.SourceCopy);
                }
            }
            else
            {
                // WindowsCapture: must capture full frame, crop after
                var images = screenshot.CaptureScreenshot().Result;
                if (images.Count == 0) return (null, 0, 0);
                using (var full = images.First())
                {
                    var cropRect = new Rectangle(cropX, cropY, side, side);
                    cropRect.Intersect(new Rectangle(0, 0, full.Width, full.Height));
                    if (cropRect.IsEmpty) region = (Bitmap)full.Clone();
                    else region = full.Clone(cropRect, full.PixelFormat);
                }
            }
            return (region, cropX, cropY);
        }

        internal static Bitmap CaptureScreenshot(bool saveDebug = true)
        {
            _window.UpdateWindow();

            // HACK: Should be already injected instead of switching here
            IScreenshotService screenshot;
            if (_windowsScreenshot == null)
            {
                // W8.1 and lower
                screenshot = _gdiScreenshot;
            }
            else
            {
                switch (_settings.HdrSupport)
                {
                    case HdrSupportEnum.On:
                        Main.AddLog("Using new windows capture API for an HDR screenshot");
                        screenshot = _windowsScreenshot;
                        break;
                    case HdrSupportEnum.Off:
                        Main.AddLog("Using old GDI service for a SDR screenshot");
                        screenshot = _gdiScreenshot;
                        break;
                    case HdrSupportEnum.Auto:
                        var isHdr = _hdrDetector.IsHDR;
                        Main.AddLog($"Automatically determining HDR status: {isHdr} | Using corresponding service");
                        screenshot = isHdr ? _windowsScreenshot : _gdiScreenshot;
                        break;
                    default:
                        throw new NotImplementedException($"HDR support option '{_settings.HdrSupport}' does not have a corresponding screenshot service.");
                }
            }

            if (ReferenceEquals(screenshot, _windowsScreenshot) && !screenshot.IsAvailable)
            {
                Main.AddLog("HDR-compliant screenshot service chosen, but unavailable. Falling back to GDI");
                screenshot = _gdiScreenshot;
            }


            var images = screenshot.CaptureScreenshot().Result;
            if (images.Count == 0)
            {
                Main.AddLog("CaptureScreenshot returned no image. Screenshot type: " + screenshot.GetType().Name);
                return null;
            }
            var image = images.First();
            if (saveDebug)
                image.Save(Main.AppPath + @"\Debug\FullScreenShot_" + DateTime.UtcNow.ToString("yyyy-MM-dd HH-mm-ssffffff", Main.culture) + ".png");
            return image;
        }

        internal static void SnapScreenshot()
        {
            var image = CaptureScreenshot(saveDebug: false);
            if (image == null)
            {
                Main.AddLog("SnapIt activation failed: Screenshot failed");
                return;
            }
            Main.snapItOverlayWindow.Populate(image);
            Main.snapItOverlayWindow.Left = _window.Window.Left / _window.DpiScaling;
            Main.snapItOverlayWindow.Top = _window.Window.Top / _window.DpiScaling;
            Main.snapItOverlayWindow.Width = _window.Window.Width / _window.DpiScaling;
            Main.snapItOverlayWindow.Height = _window.Window.Height / _window.DpiScaling;
            Main.snapItOverlayWindow.Topmost = true;
            Main.snapItOverlayWindow.Focusable = true;
            Main.snapItOverlayWindow.Show();
            Main.snapItOverlayWindow.Focus();
        }

        public static async Task UpdateEngineAsync()
        {
            await ReloadSemaphore.WaitAsync().ConfigureAwait(false);
            try {
                if (_tesseractService != null)
                    await Task.Run(() => _tesseractService.ReloadEngines()).ConfigureAwait(false);
                else
                    Main.AddLog("ERROR: Cannot reload engines - TesseractService is null");
            }
            finally {
                ReloadSemaphore.Release();
            }
        }

        #region Test Support Methods

        /// <summary>
        /// Test-only entry point: runs the reward screen OCR pipeline on a screenshot
        /// and returns the list of matched part names (English) without any UI side-effects.
        /// Requires OCR.Init and Main.dataBase to be initialized.
        /// </summary>
        internal static List<string> ProcessRewardScreenForTest(Bitmap screenshot, IWindowInfoService windowService)
        {
            var results = new List<string>();
            if (_tesseractInitFailed || _tesseractService == null)
            {
                Main.AddLog("Test ProcessReward: TesseractService is null or failed to initialize");
                return results;
            }
            windowService.UseImage(screenshot);

            List<Bitmap> parts;
            try
            {
                parts = ExtractPartBoxAutomatically(out uiScaling, out _, screenshot);
            }
            catch (Exception e)
            {
                Main.AddLog("Test ProcessReward: ExtractPartBoxAutomatically failed: " + e.Message);
                return results;
            }

            int engineCount = Math.Min(parts.Count, _tesseractService.Engines.Length);
            string[] checks = new string[parts.Count];
            Task[] tasks = new Task[engineCount];
            for (int i = 0; i < engineCount; i++)
            {
                int tempI = i;
                tasks[i] = Task.Run(() => { checks[tempI] = GetTextFromImage(parts[tempI], _tesseractService.Engines[tempI]); });
            }
            Task.WaitAll(tasks);

            // Process remaining parts sequentially if more parts than engines
            for (int i = engineCount; i < parts.Count; i++)
            {
                checks[i] = GetTextFromImage(parts[i], _tesseractService.FirstEngine);
            }

            foreach (var p in parts) p.Dispose();

            var validChecks = checks.Where(s => PartNameValid(s)).ToArray();

            foreach (var part in validChecks)
            {
                string correctName = Main.dataBase.GetPartName(part, out int dist, false, out _);
                if (dist != 9999 && dist <= GetMaxAllowedLevenshteinDistance(part.Length) && !string.IsNullOrEmpty(correctName))
                {
                    results.Add(correctName);
                }
            }

            return results;
        }

        /// <summary>
        /// Test-only entry point: runs the SnapIt OCR pipeline on a screenshot
        /// and returns the list of matched part names (English) without any UI side-effects.
        /// Requires OCR.Init and Main.dataBase to be initialized.
        /// </summary>
        internal static List<string> ProcessSnapItForTest(Bitmap screenshot, IWindowInfoService windowService)
        {
            var results = new List<string>();
            if (_tesseractInitFailed || _tesseractService == null)
            {
                Main.AddLog("Test ProcessSnapIt: TesseractService is null or failed to initialize");
                return results;
            }
            windowService.UseImage(screenshot);

            WFtheme theme = GetThemeWeighted(out _, screenshot);
            if ((int)theme < 0)
            {
                Main.AddLog("Test SnapIt: Theme detection failed");
                return results;
            }

            Bitmap filtered = ScaleUpAndFilter(screenshot, theme, out int[] rowHits, out int[] colHits);
            List<InventoryItem> foundParts = FindAllParts(filtered, screenshot, rowHits, colHits);
            filtered.Dispose();

            foreach (var part in foundParts)
            {
                if (!PartNameValid(part.Name))
                    continue;

                string name = Main.dataBase.GetPartName(part.Name, out int levenDist, false, out bool _);
                if (levenDist == 9999 || levenDist > GetMaxAllowedLevenshteinDistance(part.Name.Length) || string.IsNullOrEmpty(name))
                    continue;

                results.Add(name);
            }

            return results;
        }

